select:
/* HcpApiMyPageMapper.selectMySubCount : 나의 구독 상태별 서비스/Key 집계 */
WITH MY_KEY_IDS AS ( SELECT DISTINCT HAK.KEY_ID
FROM HCP_API_KEY HAK JOIN HCP_API_KEY_AUTH HAKA ON HAKA.KEY_ID = HAK.KEY_ID
JOIN TABLE(HCP_GET_AUTH_PRJ(#{empNo})) PRJ ON PRJ.PRJ_ID = HAKA.PRJ_ID
WHERE NOT ( HAKA.AUTH_CD = 'PSN' AND HAK.OWNER_ID != #{empNo} )
AND HAK.KEY_ID IN
#{item}
),
SUB_STATUS_INFO AS ( SELECT S.SVC_ID, S.SHOW_YN, SUB.KEY_ID, SUB.SUB_STAT_CD
FROM HCP_API_SVC S JOIN HCP_API_BASE B ON B.SVC_ID = S.SVC_ID JOIN HCP_API_PUB P ON P.API_ID = B.API_ID JOIN HCP_API_SUB SUB ON SUB.PUB_ID = P.PUB_ID JOIN MY_KEY_IDS MKI ON MKI.KEY_ID = SUB.KEY_ID
WHERE S.SVC_ENV = '${hcp.application.env}'
AND ( S.DEL_YN = 'N' OR ( S.DEL_YN = 'Y' AND S.RES_DTTM >= SYSDATE ) )
AND SUB.SUB_STAT_CD != 'CCL'
AND S.SVC_TYPE = UPPER(#{svcType})
/* * 목록과 동일한 서비스 + Key + 상태 단위 */ GROUP BY S.SVC_ID, S.SHOW_YN, SUB.KEY_ID, SUB.SUB_STAT_CD )
SELECT /* * 공개/비공개 포함 전체 구독 중 */ NVL( SUM( CASE WHEN SUB_STAT_CD = 'NOR' THEN 1 ELSE 0 END ), 0 ) AS SUB_CNT,
/* * 구독 승인 대기 * getMyAllApi(subStatus = SUB_APR)와 같은 단위 */ NVL( SUM( CASE WHEN SUB_STAT_CD = 'APR' AND SHOW_YN = 'Y' THEN 1 ELSE 0 END ), 0 ) AS APR_CNT,
/* * 공개 서비스 구독 중 */ NVL( SUM( CASE WHEN SUB_STAT_CD = 'NOR' AND SHOW_YN = 'Y' THEN 1 ELSE 0 END ), 0 ) AS SHOW_CNT,
/* * 비공개 서비스 구독 중 */ NVL( SUM( CASE WHEN SUB_STAT_CD = 'NOR' AND SHOW_YN = 'N' THEN 1 ELSE 0 END ), 0 ) AS HID_CNT,
/* * 현재 환경의 유효 서비스 전체 수 */ ( SELECT COUNT(1)
FROM HCP_API_SVC ALL_SVC
WHERE ALL_SVC.SVC_ENV = '${hcp.application.env}'
AND ( ALL_SVC.DEL_YN = 'N' OR ( ALL_SVC.DEL_YN = 'Y' AND ALL_SVC.RES_DTTM >= SYSDATE ) )
AND ALL_SVC.SVC_TYPE = UPPER(#{svcType})
) AS ALL_CNT
FROM SUB_STATUS_INFO
